+
+    [GeneratedRegex(@"uddg=([^&""]+)", RegexOptions.None)]
+    private static partial Regex UddgRegex();
+
+    [GeneratedRegex(@"<td[^>]*class=""result__snippet""[^>]*>(.*?)</td>", RegexOptions.Singleline)]
