using System.ComponentModel;

namespace ResearchAgent.Tools;

public sealed class NoteTool
{
    private readonly List<ResearchNote> _notes = [];

    [Description("Saves a research note with a topic tag and content. Use this to record key findings during research.")]
    public string SaveNote(
        [Description("A short topic tag for the note (e.g., 'definition', 'history', 'key-finding')")] string topic,
        [Description("The content of the note")] string content,
        [Description("The source URL or reference, if any")] string? source = null)
    {
        var note = new ResearchNote(
            Id: _notes.Count + 1,
            Topic: topic,
            Content: content,
            Source: source,
            Timestamp: DateTime.UtcNow);

        _notes.Add(note);
        return $"Note #{note.Id} saved under topic '{topic}'.";
    }

    [Description("Retrieves all saved research notes, optionally filtered by topic tag.")]
    public IReadOnlyList<ResearchNote> GetNotes(
        [Description("Optional topic tag to filter notes by. Leave null to get all notes.")] string? topic = null)
    {
        if (string.IsNullOrWhiteSpace(topic))
            return _notes.AsReadOnly();

        return _notes
            .Where(n => n.Topic.Contains(topic, StringComparison.OrdinalIgnoreCase))
            .ToList()
            .AsReadOnly();
    }
}

public sealed record ResearchNote(
    int Id,
    string Topic,
    string Content,
    string? Source,
    DateTime Timestamp);

