using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.RegularExpressions;
using Microsoft.Extensions.AI;

namespace ResearchAgent.Tools;

public sealed partial class WebSearchTool
{
    private readonly HttpClient _httpClient = new();

    public WebSearchTool()
    {
        _httpClient.DefaultRequestHeaders.UserAgent.ParseAdd(
            "Mozilla/5.0 (compatible; ResearchAgent/1.0)");
        _httpClient.Timeout = TimeSpan.FromSeconds(15);
    }

    [Description("Searches the web for information on a given query and returns a list of result snippets with titles and URLs.")]
    public async Task<IReadOnlyList<SearchResult>> SearchWebAsync(
        [Description("The search query string")] string query,
        [Description("Maximum number of results to return (1-10)")] int maxResults = 5,
        CancellationToken cancellationToken = default)
    {
        maxResults = Math.Clamp(maxResults, 1, 10);

        var encoded = Uri.EscapeDataString(query);
        var url = $"https://html.duckduckgo.com/html/?q={encoded}";

        var html = await _httpClient.GetStringAsync(url, cancellationToken);

        return ParseResults(html, maxResults);
    }

    [Description("Fetches the text content of a web page at the given URL for detailed reading.")]
    public async Task<string> FetchPageContentAsync(
        [Description("The URL of the page to fetch")] string url,
        CancellationToken cancellationToken = default)
    {
        try
        {
            var html = await _httpClient.GetStringAsync(url, cancellationToken);

            var text = StripHtmlRegex().Replace(html, " ");
            text = CollapseWhitespaceRegex().Replace(text, " ").Trim();

            const int maxChars = 4000;
            return text.Length > maxChars ? text[..maxChars] + "..." : text;
        }
        catch (Exception ex)
        {
            return $"Error fetching page: {ex.Message}";
        }
    }

    private static List<SearchResult> ParseResults(string html, int maxResults)
    {
        var results = new List<SearchResult>();
        var resultMatches = ResultBlockRegex().Matches(html);

        foreach (Match match in resultMatches)
        {
            if (results.Count >= maxResults)
                break;

            var block = match.Value;

            var titleMatch = TitleRegex().Match(block);
            var snippetMatch = SnippetRegex().Match(block);

            if (!titleMatch.Success)
                continue;

            var title = StripHtmlRegex().Replace(titleMatch.Groups[2].Value, "").Trim();
            var href = titleMatch.Groups[1].Value;
            var snippet = snippetMatch.Success
                ? StripHtmlRegex().Replace(snippetMatch.Groups[1].Value, "").Trim()
                : "";

            // DuckDuckGo wraps URLs in a redirect; extract the actual URL
            var uddgMatch = UddgRegex().Match(href);
            if (uddgMatch.Success)
                href = Uri.UnescapeDataString(uddgMatch.Groups[1].Value);

            if (!string.IsNullOrWhiteSpace(title))
                results.Add(new SearchResult(title, href, snippet));
        }

        return results;
    }

    [GeneratedRegex(@"<div[^>]*class=""[^""]*result[^""]*""[^>]*>.*?</div>\s*</div>", RegexOptions.Singleline)]
    private static partial Regex ResultBlockRegex();

    [GeneratedRegex(@"<a[^>]*rel=""nofollow""[^>]*href=""([^""]+)""[^>]*>(.+?)</a>", RegexOptions.Singleline)]
    private static partial Regex TitleRegex();

    [GeneratedRegex(@"uddg=([^&""]+)", RegexOptions.None)]
    private static partial Regex UddgRegex();

    [GeneratedRegex(@"<td[^>]*class=""result__snippet""[^>]*>(.*?)</td>", RegexOptions.Singleline)]
    private static partial Regex SnippetRegex();

    [GeneratedRegex(@"<[^>]+>")]
    private static partial Regex StripHtmlRegex();

    [GeneratedRegex(@"\s+")]
    private static partial Regex CollapseWhitespaceRegex();
}

public sealed record SearchResult(string Title, string Url, string Snippet);

