using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using OpenAI;
using ResearchAgent.Tools;

// --- Configuration ---
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// --- DI setup ---
var services = new ServiceCollection();

services.AddLogging(b => b.AddConsole().SetMinimumLevel(LogLevel.Warning));
services.AddHttpClient("WebSearch");

// Register tools (NoteTool is stateful per session, so scoped/singleton)
services.AddSingleton<NoteTool>();
services.AddTransient<WebSearchTool>();

// Register the chat client through MEAI abstraction
services.AddChatClient(builder => builder
    .UseOpenAIChatClient(modelId, new OpenAIClient(apiKey)));

await using var sp = services.BuildServiceProvider();

var chatClient = sp.GetRequiredService<IChatClient>();
var noteTool = sp.GetRequiredService<NoteTool>();
var webSearchTool = sp.GetRequiredService<WebSearchTool>();

// --- Build tool list using AIFunctionFactory ---
var tools = new AITool[]
{
    AIFunctionFactory.Create(webSearchTool.SearchWebAsync),
    AIFunctionFactory.Create(webSearchTool.FetchPageContentAsync),
    AIFunctionFactory.Create(noteTool.SaveNote),
    AIFunctionFactory.Create(noteTool.GetNotes),
};

// --- Create the agent ---
var agent = new ChatClientAgent(chatClient, "ResearchAgent")
{
    Instructions = """
        You are a research agent. Your job is to thoroughly research a topic the user provides.

        Follow this workflow:
        1. Search the web for the topic using SearchWebAsync.
        2. Review the search results and fetch the most promising pages using FetchPageContentAsync.
        3. Save important findings as notes using SaveNote with descriptive topic tags.
        4. If needed, do follow-up searches to fill gaps in your understanding.
        5. Once you have gathered enough information, retrieve all notes using GetNotes.
        6. Synthesize your notes into a comprehensive, well-structured summary.

        Guidelines:
        - Always cite sources with URLs when available.
        - Save at least 3-5 notes before summarizing.
        - Be thorough but concise in your final summary.
        - Organize the summary with clear sections.
        """,
};

// --- Run the agent ---
Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║     🔍 AI Research Agent             ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();
Console.Write("Enter a topic to research: ");
var topic = Console.ReadLine()?.Trim();

if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine();
Console.WriteLine($"Researching: {topic}");
Console.WriteLine("This may take a minute...");
Console.WriteLine();

var history = new List<ChatMessage>
{
    new(ChatRole.User, $"Research the following topic and provide a comprehensive summary: {topic}"),
};

var options = new AgentInvokeOptions
{
    MaximumIterations = 15,
    Tools = tools,
    ModelOptions = new ChatOptions
    {
        Temperature = 0f,
        MaxOutputTokens = 4096,
    },
};

try
{
    await foreach (var message in agent.InvokeStreamingAsync(history, options))
    {
        if (message.Role == ChatRole.Assistant && !string.IsNullOrEmpty(message.Text))
        {
            Console.Write(message.Text);
        }
    }

    Console.WriteLine();
    Console.WriteLine();
    Console.WriteLine("── Research complete ──");

    // Show saved notes summary
    var allNotes = noteTool.GetNotes();
    if (allNotes.Count > 0)
    {
        Console.WriteLine($"Notes collected: {allNotes.Count}");
        foreach (var note in allNotes)
        {
            Console.WriteLine($"  • [{note.Topic}] {note.Content[..Math.Min(80, note.Content.Length)]}...");
        }
    }
}
catch (Exception ex)
{
    Console.Error.WriteLine($"Error during research: {ex.Message}");
    Environment.ExitCode = 1;
}

